module.exports = BobEmojiPlugin;
module.exports.helpers = {
  BOB_EMOJI_CATALOG,
  BOB_EMOJI_POPULAR,
  BOB_EMOJI_RECENTS_LIMIT,
  BOB_EMOJI_SUGGESTION_LIMIT,
  BobEmojiSuggest,
  emojiNormalizeQuery,
  emojiBuildIndex,
  emojiNormalizeRecents,
  emojiRecordRecent,
  emojiSearch,
  emojiOffsetAt,
  emojiContextAllows,
  emojiFindTrigger,
};
